device_initialize.body:
void device_initialize(struct device *dev)
{
	__module_get(dev->release_owner);
	dev->kobj.kset = devices_kset;
	kobject_init(&dev->kobj, &device_ktype);
	INIT_LIST_HEAD(&dev->dma_pools);
	mutex_init(&dev->mutex);
	spin_lock_init(&dev->driver_override.lock);
	lockdep_set_novalidate_class(&dev->mutex);
	spin_lock_init(&dev->devres_lock);
	INIT_LIST_HEAD(&dev->devres_head);
	device_pm_init(dev);
	set_dev_node(dev, NUMA_NO_NODE);
	INIT_LIST_HEAD(&dev->links.consumers);
	INIT_LIST_HEAD(&dev->links.suppliers);
	INIT_LIST_HEAD(&dev->links.defer_sync);
	dev->links.status = DL_DEV_NO_DRIVER;
	dev_assign_dma_coherent(dev, dma_default_coherent);
	swiotlb_dev_init(dev);
}

device_release.body:
static void device_release(struct kobject *kobj)
{
	struct device *dev = kobj_to_dev(kobj);
	struct device_private *p = dev->p;
	struct module *owner = dev->release_owner;

	/*
	 * Some platform devices are driven without driver attached
	 * and managed resources may have been acquired.  Make sure
	 * all resources are released.
	 *
	 * Drivers still can add resources into device after device
	 * is deleted but alive, so release devres here to avoid
	 * possible memory leak.
	 */
	devres_release_all(dev);

	kfree(dev->dma_range_map);
	kfree(dev->driver_override.name);

	if (dev->release)
		dev->release(dev);
	else if (dev->type && dev->type->release)
		dev->type->release(dev);
	else if (dev->class && dev->class->dev_release)
		dev->class->dev_release(dev);
	else
		WARN(1, KERN_ERR "Device '%s' does not have a release() function, it is broken and must be fixed. See Documentation/core-api/kobject.rst.\n",
			dev_name(dev));
	kfree(p);
	module_put(owner);
}

add_mtd_device.body:
int add_mtd_device(struct mtd_info *mtd)
{
	DECLARE_COMPLETION_ONSTACK(released);
	struct device_node *np = mtd_get_of_node(mtd);
	struct mtd_info *master = mtd_get_master(mtd);
	struct mtd_notifier *not;
	int i, error, ofidx;
	u32 id;
	bool wait_for_release = false;

	/*
	 * May occur, for instance, on buggy drivers which call
	 * mtd_device_parse_register() multiple times on the same master MTD,
	 * especially with CONFIG_MTD_PARTITIONED_MASTER=y.
	 */
	if (WARN_ONCE(mtd->dev.type, "MTD already registered\n"))
		return -EEXIST;

	BUG_ON(mtd->writesize == 0);

	/*
	 * MTD drivers should implement ->_{write,read}() or
	 * ->_{write,read}_oob(), but not both.
	 */
	if (WARN_ON((mtd->_write && mtd->_write_oob) ||
		    (mtd->_read && mtd->_read_oob)))
		return -EINVAL;

	if (WARN_ON((!mtd->erasesize || !master->_erase) &&
		    !(mtd->flags & MTD_NO_ERASE)))
		return -EINVAL;

	/*
	 * MTD_SLC_ON_MLC_EMULATION can only be set on partitions, when the
	 * master is an MLC NAND and has a proper pairing scheme defined.
	 * We also reject masters that implement ->_writev() for now, because
	 * NAND controller drivers don't implement this hook, and adding the
	 * SLC -> MLC address/length conversion to this path is useless if we
	 * don't have a user.
	 */
	if (mtd->flags & MTD_SLC_ON_MLC_EMULATION &&
	    (!mtd_is_partition(mtd) || master->type != MTD_MLCNANDFLASH ||
	     !master->pairing || master->_writev))
		return -EINVAL;

	mutex_lock(&mtd_table_mutex);

	ofidx = -1;
	if (np)
		ofidx = of_alias_get_id(np, "mtd");
	if (ofidx >= 0)
		i = ida_alloc_range(&mtd_ids, ofidx, ofidx, GFP_KERNEL);
	else
		i = ida_alloc(&mtd_ids, GFP_KERNEL);
	if (i < 0) {
		error = i;
		goto fail_locked;
	}
	id = i;
	error = idr_alloc_u32(&mtd_idr, mtd, &id, id, GFP_KERNEL);
	if (error) {
		ida_free(&mtd_ids, i);
		goto fail_locked;
	}

	mtd->index = i;
	kref_init(&mtd->refcnt);
	if (master->master.release) {
		mtd_get_lifetime(master);
		mtd->ref_master = master;
		if (mtd->parent && mtd->parent != master)
			get_device(&mtd->parent->dev);
	}

	/* default value if not set by driver */
	if (mtd->bitflip_threshold == 0)
		mtd->bitflip_threshold = mtd->ecc_strength;

	if (mtd->flags & MTD_SLC_ON_MLC_EMULATION) {
		int ngroups = mtd_pairing_groups(master);

		mtd->erasesize /= ngroups;
		mtd->size = (u64)mtd_div_by_eb(mtd->size, master) *
			    mtd->erasesize;
	}

	if (is_power_of_2(mtd->erasesize))
		mtd->erasesize_shift = ffs(mtd->erasesize) - 1;
	else
		mtd->erasesize_shift = 0;

	if (is_power_of_2(mtd->writesize))
		mtd->writesize_shift = ffs(mtd->writesize) - 1;
	else
		mtd->writesize_shift = 0;

	mtd->erasesize_mask = (1 << mtd->erasesize_shift) - 1;
	mtd->writesize_mask = (1 << mtd->writesize_shift) - 1;

	/* Some chips always power up locked. Unlock them now */
	if ((mtd->flags & MTD_WRITEABLE) && (mtd->flags & MTD_POWERUP_LOCK)) {
		error = mtd_unlock(mtd, 0, mtd->size);
		if (error && error != -EOPNOTSUPP)
			printk(KERN_WARNING
			       "%s: unlock failed, writes may not work\n",
			       mtd->name);
		/* Ignore unlock failures? */
		error = 0;
	}

	/* Caller should have set dev.parent to match the
	 * physical device, if appropriate.
	 */
	mtd->dev.class = &mtd_class;
	mtd->dev.devt = MTD_DEVT(i);
	error = dev_set_name(&mtd->dev, "mtd%d", i);
	if (error)
		goto fail_devname;
	mtd->dev.type = &mtd_devtype;
	mtd->dev.release_owner = THIS_MODULE;
	dev_set_drvdata(&mtd->dev, mtd);
	mtd_set_of_node(mtd, mtd_find_of_node(mtd));
	error = device_register(&mtd->dev);
	if (error)
		goto fail_added;

	/* Add the nvmem provider */
	error = mtd_nvmem_add(mtd);
	if (error)
		goto fail_nvmem_add;

	mtd_debugfs_populate(mtd);

	device_create(&mtd_class, mtd->dev.parent, MTD_DEVT(i) + 1, NULL,
		      "mtd%dro", i);

	pr_debug("mtd: Giving out device %d to %s\n", i, mtd->name);
	mtd->registered = true;
	/* No need to get a refcount on the module containing
	   the notifier, since we hold the mtd_table_mutex */
	list_for_each_entry(not, &mtd_notifiers, list)
		not->add(mtd);

	mutex_unlock(&mtd_table_mutex);

	if (of_property_read_bool(mtd_get_of_node(mtd), "linux,rootfs")) {
		if (IS_BUILTIN(CONFIG_MTD)) {
			pr_info("mtd: setting mtd%d (%s) as root device\n", mtd->index, mtd->name);
			ROOT_DEV = MKDEV(MTD_BLOCK_MAJOR, mtd->index);
		} else {
			pr_warn("mtd: can't set mtd%d (%s) as root device - mtd must be builtin\n",
				mtd->index, mtd->name);
		}
	}

	return 0;

fail_nvmem_add:
	device_del(&mtd->dev);
fail_added:
	/*
	 * Clear type and override release to prevent mtd_release() ->
	 * release_mtd_partition() -> free_partition() from freeing mtd.
	 * The caller handles cleanup on failure.
	 */
	mtd->dev.type = NULL;
	mtd->dev.release = mtd_dev_release_done;
	dev_set_drvdata(&mtd->dev, &released);
	wait_for_release = true;
	put_device(&mtd->dev);
	of_node_put(mtd_get_of_node(mtd));
fail_devname:
	idr_remove(&mtd_idr, i);
	ida_free(&mtd_ids, i);
	if (mtd->ref_master) {
		mtd->ref_master = NULL;
		if (mtd->parent && mtd->parent != master)
			put_device(&mtd->parent->dev);
		mtd_put_lifetime(master);
	}
fail_locked:
	mutex_unlock(&mtd_table_mutex);
	if (wait_for_release) {
		wait_for_completion(&released);
		mtd->dev.release = NULL;
		dev_set_drvdata(&mtd->dev, mtd);
	}
	return error;
}

mtd_release.body:
static void mtd_release(struct device *dev)
{
	struct mtd_info *mtd = dev_get_drvdata(dev);
	struct mtd_info *master = mtd->ref_master;
	struct mtd_info *parent = mtd->parent;

	/* Retained NVMEM providers use the MTD number in their device name. */
	ida_free(&mtd_ids, mtd->index);
	of_node_put(mtd_get_of_node(mtd));

	if (mtd_is_partition(mtd))
		release_mtd_partition(mtd);

	if (master) {
		/* Nested partitions can outlive device_del() of their parents. */
		if (parent && parent != master)
			put_device(&parent->dev);
		mtd_put_lifetime(master);
	}
}
